import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long a = 0;
        long b = 1;
        for (int i = 0; i < n - 1; i++) {
            long t = a + b;
            a = b;
            b = t;
        }
        System.out.println(a);
    }
}

